<script module lang="ts">
/**
 * Two regions on one axis, resized by a draggable or keyboard-stepped divider (`design/components/split-pane.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/split-pane.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import { agentMember, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/layout/split-pane.module.css'

export type SplitPaneOrientation = NonNullable<SplitPaneProps['orientation']>

export interface SplitPaneProps {
  defaultRatio?: number
  /**
   * The second pane.
   */
  end: Snippet
  endMin?: number
  /**
   * The separator's accessible name, such as "Resize navigator" rather than "Divider".
   */
  label: string
  /**
   * Fires on release and after each keyboard step, like Slider's `onCommit`, so apps can persist
   * the layout without debouncing `onRatioChange`.
   */
  onCommit?: (ratio: number) => void
  onRatioChange?: (ratio: number) => void
  /**
   * The axis of the panes; `horizontal` means side by side, as in Stepper.
   */
  orientation?: 'horizontal' | 'vertical'
  /**
   * The start pane's share, 0–1, controlled like Slider's value.
   */
  ratio?: number
  /**
   * The first pane in reading order: inline-start, or block-start when stacked.
   */
  start: Snippet
  /**
   * Content floors in px, drawn by `minmax()` and respected by the keyboard clamp.
   */
  startMin?: number
}
</script>

<script lang="ts">
let {
  defaultRatio = 0.5,
  end,
  endMin = 0,
  label: labelOwn,
  onCommit,
  onRatioChange,
  orientation = 'horizontal',
  ratio,
  start,
  startMin = 0,
}: SplitPaneProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
// svelte-ignore state_referenced_locally
let mirror = $state(Math.min(1, Math.max(0, defaultRatio)))
let dragging = $state(false)
let bounds = $state({ min: 0, max: 1 })
// svelte-ignore state_referenced_locally
let latest = $state(Math.min(1, Math.max(0, ratio ?? defaultRatio)))
let divider = $state<HTMLElement | null>(null)
let root = $state<HTMLElement | null>(null)
const horizontal = $derived(orientation === 'horizontal')
const current = $derived(Math.min(1, Math.max(0, ratio ?? mirror)))
const clamp = $derived((value: number) => Math.min(bounds.max, Math.max(bounds.min, value)))
const effective = $derived(clamp(current))
const startId = $derived(`${uid}-start`)
const move = $derived((next: number) => {
  const clamped = Math.round(clamp(Math.min(1, Math.max(0, next))) * 10000) / 10000
  if (clamped === latest) return
  latest = clamped
  mirror = clamped
  onRatioChange?.(clamped)
})
const measure = $derived(() => {
  if (root === null) return
  const box = root.getBoundingClientRect()
  const line = divider?.getBoundingClientRect()
  const usable =
    (horizontal ? box.width : box.height) -
    (line === undefined ? 0 : horizontal ? line.width : line.height)
  if (usable <= 0 || startMin + endMin >= usable) {
    bounds = { min: 0, max: 1 }
    return
  }
  bounds = {
    min: Math.min(1, Math.max(0, startMin / usable)),
    max: Math.min(1, Math.max(0, 1 - endMin / usable)),
  }
})
const pointerDown = $derived((event: PointerEvent) => {
  try {
    ;(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId)
  } catch {
    /* an inactive pointer: nothing to capture */
  }
  dragging = true
})
const pointerMove = $derived((event: PointerEvent) => {
  if (!dragging || root === null) return
  const box = root.getBoundingClientRect()
  const handle = (event.currentTarget as HTMLElement).getBoundingClientRect()
  const thickness = horizontal ? handle.width : handle.height
  const usable = (horizontal ? box.width : box.height) - thickness
  if (usable <= 0) return
  const rtl = horizontal && getComputedStyle(root).direction === 'rtl'
  const along = horizontal
    ? rtl
      ? box.right - event.clientX
      : event.clientX - box.left
    : event.clientY - box.top
  move((along - thickness / 2) / usable)
})
const pointerUp = $derived((event: PointerEvent) => {
  if (!dragging) return
  const target = event.currentTarget as HTMLElement
  if (target.hasPointerCapture(event.pointerId)) target.releasePointerCapture(event.pointerId)
  dragging = false
  onCommit?.(latest)
})
const keyDown = $derived((event: KeyboardEvent) => {
  const rtl = horizontal && getComputedStyle(event.currentTarget as HTMLElement).direction === 'rtl'
  const grow = horizontal ? (rtl ? 'ArrowLeft' : 'ArrowRight') : 'ArrowDown'
  const shrink = horizontal ? (rtl ? 'ArrowRight' : 'ArrowLeft') : 'ArrowUp'
  let next: number
  switch (event.key) {
    case grow:
      next = current + 0.02
      break
    case shrink:
      next = current - 0.02
      break
    case 'PageUp':
      next = current + 0.1
      break
    case 'PageDown':
      next = current - 0.1
      break
    case 'Home':
      next = bounds.min
      break
    case 'End':
      next = bounds.max
      break
    default:
      return
  }
  event.preventDefault()
  move(next)
  onCommit?.(latest)
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    measure()
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [root]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect1, { watch: () => [orientation, startMin, endMin] })
onDestroy(() => release1?.())
const effect2 = () => {
  latest = current
}
watchEffect(effect2, { watch: () => current, mount: false })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'SplitPane',
    element: () => divider,
    state: () => ({ position: Math.round(effective * 100) }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            move(value / 100)
            onCommit?.(latest)
          })(),
      },
    },
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.root}
    style:--pm-split-start={`${effective}fr`}
    style:--pm-split-end={`${1 - effective}fr`}
    style:--pm-split-start-min={`${startMin}px`}
    style:--pm-split-end-min={`${endMin}px`}
    data-orientation={orientation}
    data-member="split-pane"
    ><div class={styles.pane} id={startId}>{@render start?.()}</div
    ><div
      bind:this={divider}
      class={styles.divider}
      data-split-pane-part="divider"
      role="separator"
      tabindex="0"
      aria-label={label}
      aria-orientation={horizontal ? 'vertical' : 'horizontal'}
      aria-controls={startId}
      aria-valuenow={Math.round(effective * 100)}
      aria-valuemin={Math.round(bounds.min * 100)}
      aria-valuemax={Math.round(bounds.max * 100)}
      data-state={dragging ? 'dragging' : undefined}
      onpointerdown={(event) => { pointerDown(event) }}
      onpointermove={(event) => { pointerMove(event) }}
      onpointerup={(event) => { pointerUp(event) }}
      onpointercancel={(event) => { pointerUp(event) }}
      onkeydown={(event) => { keyDown(event) }}
    ></div
    ><div class={styles.pane}>{@render end?.()}</div
  ></div
>{/if
}{@render joined.end?.()}
